<template>
  <div class="card top">
    <div class="title">{{ title }}</div>
    <div class="wrap">
      <a-image v-if="deviceData?.picture" class="device-img" :height="180" :src="deviceData?.picture"></a-image>
      <a-image v-else class="device-img" :height="180" :src="devicePng"></a-image>
      <a-descriptions style="margin-left:20px;">
        <template #title>
          <span style="display:inline-block;margin-right: 5px;">{{deviceData?.baseArchivesInfo.name}}</span>
          <a-tag v-if="deviceData?.baseArchivesInfo.status.onlineState" color='#87d068'>在线</a-tag>
          <a-tag v-else color='#fba33f'>离线</a-tag>
        </template>
        <a-descriptions-item label="设备名称">{{ deviceData?.baseArchivesInfo.name || '--'}}</a-descriptions-item>
        <a-descriptions-item label="产品名称">{{ deviceData?.productInfo.name || '--'}}</a-descriptions-item>
        <a-descriptions-item label="产品分类">{{ deviceData?.productInfo.productCategory.name || '--'}}</a-descriptions-item>
        <a-descriptions-item label="设备编码">{{ deviceData?.baseArchivesInfo.code  || '--'}}</a-descriptions-item>
        <a-descriptions-item label="设备型号">{{ deviceData?.productInfo.modelName  || '--'}}</a-descriptions-item>
        <a-descriptions-item label="设备品牌">{{ deviceData?.productInfo.brandName || '--'}}</a-descriptions-item>
        <a-descriptions-item label="所属区域">{{ deviceData?.areaName || '--'}}</a-descriptions-item>
      </a-descriptions>
    </div>
  </div>
</template>

<script lang="jsx">
import {
  computed,
  defineComponent, getCurrentInstance, onBeforeMount,
  onMounted, reactive, ref, toRefs, watch,
} from "vue";
const devicePng = "data:image/png;base64,"
  
export default defineComponent({
  props: {
    title: {
      type: String,
      default: "",
    },
    baseInfo: {
      type: Object,
      default: {
        fileVO: {
          path: "",
        },
        picture: ""
      }
    },
  },
  setup(props, { emit }) {
    const state = reactive({
      deviceData:{
        ...{
          fileVO: {
            path: "",
          }
        },
        picture: '',
        ...props.baseInfo
      },
    })
    watch(() => props.baseInfo, (newVal) => {
      state.deviceData = newVal
    },{deep:true, immediate: true})
    return {
      ...toRefs(state),
      devicePng,
    };
  },
});
</script>
